from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('app/ml/backtest.py', 'from __future__ import annotations\n\nimport math\nfrom typing import Any\n\nimport numpy as np\nimport pandas as pd\n\nfrom app.ml.bundle import ModelBundle\nfrom app.ml.distributions import binary_log_loss\nfrom app.ml.features import ALL_FEATURES, TARGET_COLUMN, normalize_training_frame\n\n\ndef run_backtest(\n    bundle: ModelBundle,\n    frame: pd.DataFrame,\n    configuration: dict[str, Any],\n) -> tuple[dict[str, Any], list[dict[str, Any]]]:\n    frame = normalize_training_frame(frame)\n    if frame.empty:\n        raise ValueError("Backtest dataset has no valid rows.")\n\n    minimum_net_edge = float(configuration.get("minimum_net_edge", 0.03))\n    fee_multiplier = float(configuration.get("fee_multiplier", 0.07))\n    slippage = float(configuration.get("slippage_per_contract", 0.01))\n    uncertainty = float(configuration.get("uncertainty_buffer", 0.01))\n    contracts = int(configuration.get("contracts_per_trade", 1))\n    max_exposure = float(configuration.get("maximum_total_exposure", 1000.0))\n\n    trades: list[dict[str, Any]] = []\n    predictions: list[float] = []\n    actuals: list[float] = []\n    probabilities: list[float] = []\n    outcomes: list[int] = []\n    cumulative_pnl = 0.0\n    peak_pnl = 0.0\n    maximum_drawdown = 0.0\n    active_exposure = 0.0\n\n    has_market_fields = {"market_yes_ask", "lower_bound", "upper_bound"}.issubset(frame.columns)\n\n    for _, row_series in frame.iterrows():\n        row = {column: row_series.get(column) for column in ALL_FEATURES}\n        predicted, q10, q90, sigma = bundle.predict_value(row)\n        actual = float(row_series[TARGET_COLUMN])\n        predictions.append(predicted)\n        actuals.append(actual)\n\n        if not has_market_fields:\n            continue\n        ask = row_series.get("market_yes_ask")\n        lower = row_series.get("lower_bound")\n        upper = row_series.get("upper_bound")\n        if pd.isna(ask) or (pd.isna(lower) and pd.isna(upper)):\n            continue\n        ask = float(ask)\n        lower_value = None if pd.isna(lower) else float(lower)\n        upper_value = None if pd.isna(upper) else float(upper)\n        raw, probability = bundle.predict_event(row, lower_value, upper_value)\n        outcome = int(\n            (lower_value is None or actual >= lower_value)\n            and (upper_value is None or actual < upper_value)\n        )\n        probabilities.append(probability)\n        outcomes.append(outcome)\n        fee = fee_multiplier * ask * (1.0 - ask)\n        net_edge = probability - ask - fee - slippage - uncertainty\n        requested_exposure = ask * contracts\n        if net_edge < minimum_net_edge or active_exposure + requested_exposure > max_exposure:\n            continue\n        pnl_per_contract = outcome - ask - fee - slippage\n        pnl = pnl_per_contract * contracts\n        cumulative_pnl += pnl\n        peak_pnl = max(peak_pnl, cumulative_pnl)\n        maximum_drawdown = max(maximum_drawdown, peak_pnl - cumulative_pnl)\n        active_exposure += requested_exposure\n        trades.append(\n            {\n                "target_time": str(row_series.get("target_time")),\n                "station_code": row_series.get("station_code"),\n                "predicted_value": round(predicted, 4),\n                "actual_value": actual,\n                "raw_probability": round(raw, 6),\n                "calibrated_probability": round(probability, 6),\n                "market_yes_ask": ask,\n                "estimated_fee": round(fee, 6),\n                "slippage": slippage,\n                "uncertainty_buffer": uncertainty,\n                "net_edge": round(net_edge, 6),\n                "contracts": contracts,\n                "event_outcome": outcome,\n                "pnl": round(pnl, 6),\n                "cumulative_pnl": round(cumulative_pnl, 6),\n                "prediction_interval": [round(q10, 4), round(q90, 4)],\n                "sigma": round(sigma, 4),\n            }\n        )\n\n    errors = np.asarray(predictions) - np.asarray(actuals)\n    metrics: dict[str, Any] = {\n        "rows": len(frame),\n        "mae": float(np.mean(np.abs(errors))),\n        "rmse": float(np.sqrt(np.mean(errors**2))),\n        "bias": float(np.mean(errors)),\n        "trades": len(trades),\n        "total_pnl": round(cumulative_pnl, 6),\n        "maximum_drawdown": round(maximum_drawdown, 6),\n        "win_rate": (\n            float(np.mean([trade["pnl"] > 0 for trade in trades])) if trades else 0.0\n        ),\n        "average_net_edge": (\n            float(np.mean([trade["net_edge"] for trade in trades])) if trades else 0.0\n        ),\n        "total_fees": round(sum(trade["estimated_fee"] * trade["contracts"] for trade in trades), 6),\n        "total_slippage": round(sum(trade["slippage"] * trade["contracts"] for trade in trades), 6),\n    }\n    if probabilities:\n        probability_array = np.asarray(probabilities)\n        outcome_array = np.asarray(outcomes)\n        metrics.update(\n            {\n                "brier_score": float(np.mean((probability_array - outcome_array) ** 2)),\n                "log_loss": float(\n                    np.mean(\n                        [\n                            binary_log_loss(probability, int(outcome))\n                            for probability, outcome in zip(probability_array, outcome_array, strict=True)\n                        ]\n                    )\n                ),\n                "probability_samples": len(probabilities),\n            }\n        )\n    else:\n        metrics.update({"brier_score": math.nan, "log_loss": math.nan, "probability_samples": 0})\n    return metrics, trades\n')
write('app/ml/bundle.py', 'from __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.isotonic import IsotonicRegression\n\nfrom app.ml.distributions import bracket_probability, clamp_probability, sigma_from_quantiles\nfrom app.ml.features import ALL_FEATURES, NUMERIC_FEATURES\n\n\n@dataclass\nclass ModelBundle:\n    version: str\n    feature_schema_version: str\n    median_model: Any\n    lower_model: Any\n    upper_model: Any\n    calibrator: IsotonicRegression | None\n    residual_std: float\n    feature_reference: dict[str, Any]\n    supported_stations: list[str]\n    supported_market_types: list[str]\n    training_examples: list[dict[str, Any]] = field(default_factory=list)\n    metrics: dict[str, Any] = field(default_factory=dict)\n    metadata: dict[str, Any] = field(default_factory=dict)\n\n    def frame(self, row: dict[str, Any]) -> pd.DataFrame:\n        return pd.DataFrame([{column: row.get(column) for column in ALL_FEATURES}])\n\n    def predict_value(self, row: dict[str, Any]) -> tuple[float, float, float, float]:\n        frame = self.frame(row)\n        median = float(self.median_model.predict(frame)[0])\n        lower = float(self.lower_model.predict(frame)[0])\n        upper = float(self.upper_model.predict(frame)[0])\n        if lower > upper:\n            lower, upper = upper, lower\n        lower = min(lower, median)\n        upper = max(upper, median)\n        sigma = max(sigma_from_quantiles(lower, upper), self.residual_std * 0.35, 0.25)\n        return median, lower, upper, sigma\n\n    def raw_event_probability(\n        self,\n        row: dict[str, Any],\n        lower_bound: float | None,\n        upper_bound: float | None,\n    ) -> float:\n        median, _, _, sigma = self.predict_value(row)\n        return bracket_probability(median, sigma, lower_bound, upper_bound)\n\n    def raw_event_probability_with_sigma(\n        self,\n        mean: float,\n        sigma: float,\n        lower_bound: float | None,\n        upper_bound: float | None,\n    ) -> float:\n        return bracket_probability(mean, sigma, lower_bound, upper_bound)\n\n    def calibrate(self, raw_probability: float) -> float:\n        if self.calibrator is None:\n            return clamp_probability(raw_probability)\n        calibrated = float(self.calibrator.predict([raw_probability])[0])\n        return clamp_probability(calibrated)\n\n    def predict_event(\n        self,\n        row: dict[str, Any],\n        lower_bound: float | None,\n        upper_bound: float | None,\n    ) -> tuple[float, float]:\n        raw = self.raw_event_probability(row, lower_bound, upper_bound)\n        return raw, self.calibrate(raw)\n\n    def explain(self, row: dict[str, Any], limit: int = 8) -> list[dict[str, Any]]:\n        base_prediction = self.predict_value(row)[0]\n        contributions: list[dict[str, Any]] = []\n        for feature in NUMERIC_FEATURES:\n            current = row.get(feature)\n            reference = self.feature_reference.get(feature)\n            if current is None or reference is None:\n                continue\n            perturbed = dict(row)\n            perturbed[feature] = reference\n            reference_prediction = self.predict_value(perturbed)[0]\n            contribution = base_prediction - reference_prediction\n            if abs(contribution) < 1e-5:\n                continue\n            contributions.append(\n                {\n                    "feature": feature,\n                    "contribution": round(float(contribution), 5),\n                    "current_value": current,\n                    "reference_value": reference,\n                    "direction": "positive" if contribution > 0 else "negative",\n                }\n            )\n        return sorted(contributions, key=lambda item: abs(item["contribution"]), reverse=True)[:limit]\n\n    def analogues(self, row: dict[str, Any], limit: int = 5) -> list[dict[str, Any]]:\n        if not self.training_examples:\n            return []\n        scales = self.metadata.get("feature_scales", {})\n        candidates: list[tuple[float, dict[str, Any]]] = []\n        analogue_features = [\n            "forecast_mean",\n            "forecast_std",\n            "lead_hours",\n            "latest_temperature",\n            "humidity",\n            "wind_speed",\n            "cloud_cover",\n            "doy_sin",\n            "doy_cos",\n        ]\n        for example in self.training_examples:\n            distance = 0.0\n            count = 0\n            for feature in analogue_features:\n                left = row.get(feature)\n                right = example.get(feature)\n                if left is None or right is None:\n                    continue\n                try:\n                    scale = max(float(scales.get(feature, 1.0)), 1e-6)\n                    distance += ((float(left) - float(right)) / scale) ** 2\n                    count += 1\n                except (TypeError, ValueError):\n                    continue\n            if count:\n                candidates.append((float(np.sqrt(distance / count)), example))\n        candidates.sort(key=lambda item: item[0])\n        return [\n            {\n                "distance": round(distance, 4),\n                "target_time": example.get("target_time"),\n                "station_code": example.get("station_code"),\n                "forecast_mean": example.get("forecast_mean"),\n                "actual_value": example.get("actual_value"),\n            }\n            for distance, example in candidates[:limit]\n        ]\n')
